{"code": "import subprocess
import time

# Restart hermes-api and hermes-worker
for container in ["hermes-api", "hermes-worker"]:
    result = subprocess.run(["docker", "restart", container], capture_output=True, text=True, timeout=30)
    print(f"Restart {container}: {result.stdout.strip()}")

print("\nWaiting for containers to start (15s)...")
time.sleep(15)

# Check if they are healthy
result = subprocess.run(["docker", "ps", "--format", "{{.Names}} {{.Status}}"], capture_output=True, text=True, timeout=10)
for line in result.stdout.splitlines():
